import {
  compareWithCurrent,
  createSnapshot,
  type Issue,
  type ProjectSnapshot,
  readSnapshot,
  type TemplateDefinition,
  type VersionReport,
} from '@kerf/core';
import { desc, eq } from 'drizzle-orm';
import { z } from 'zod';
import type { Database } from '../db/client.ts';
import { PROJECT_STATUSES, projects } from '../db/schema.ts';

// Projects and their stored snapshots (ARCHITECTURE.md, apps/api). Snapshots are generated by
// core and stored; reads parse them back and compare them with the template's current version.
// Regenerating is always explicit: a new snapshot is made only on create, when the parameters or
// structural inputs change, or on request.

export const ProjectStatus = z.enum(PROJECT_STATUSES);

export const NewProject = z.object({
  name: z.string().trim().min(1).max(200),
  templateId: z.string(),
  status: ProjectStatus.default('planned'),
  params: z.unknown(),
  /** Structural inputs have no defaults; an empty object leaves every check "input needed". */
  structuralInputs: z.unknown(),
});
export type NewProject = z.infer<typeof NewProject>;

export const ProjectChanges = z
  .object({
    name: z.string().trim().min(1).max(200),
    status: ProjectStatus,
    params: z.unknown(),
    structuralInputs: z.unknown(),
  })
  .partial()
  .refine((c) => Object.values(c).some((v) => v !== undefined), 'changes nothing');
export type ProjectChanges = z.infer<typeof ProjectChanges>;

export interface ProjectSummary {
  id: string;
  name: string;
  status: z.infer<typeof ProjectStatus>;
  templateId: string;
  templateVersion: number;
  /** True when the template has a newer version than the one the snapshot was made with. */
  templateBehind: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface Project extends ProjectSummary {
  /** Null when the stored snapshot cannot be read; `unreadable` says why. */
  snapshot: ProjectSnapshot | null;
  unreadable?: { reason: string; message: string };
  version: VersionReport;
}

export type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: 'not-found' | 'unknown-template' }
  | { ok: false; error: 'invalid-project'; issues: Issue[] };

type Row = typeof projects.$inferSelect;

const StoredEnvelope = z.object({ outputs: z.unknown() });

export function createProjectService(deps: {
  db: Database;
  templates: readonly TemplateDefinition[];
  now: () => Date;
}) {
  const { db, templates, now } = deps;
  const findTemplate = (id: string) => templates.find((t) => t.id === id);

  function summary(row: Row): ProjectSummary {
    const template = findTemplate(row.templateId);
    return {
      id: row.id,
      name: row.name,
      status: ProjectStatus.parse(row.status),
      templateId: row.templateId,
      templateVersion: row.templateVersion,
      templateBehind: template !== undefined && row.templateVersion < template.version,
      createdAt: row.createdAt.toISOString(),
      updatedAt: row.updatedAt.toISOString(),
    };
  }

  function view(row: Row): Result<Project> {
    const template = findTemplate(row.templateId);
    if (!template) return { ok: false, error: 'unknown-template' };
    const read = readSnapshot(templates, row.snapshot);
    const stored = StoredEnvelope.safeParse(row.snapshot);
    return {
      ok: true,
      value: {
        ...summary(row),
        snapshot: read.ok ? read.snapshot : null,
        ...(read.ok ? {} : { unreadable: { reason: read.reason, message: read.message } }),
        version: compareWithCurrent(template, {
          templateVersion: row.templateVersion,
          params: row.params,
          structuralInputs: row.structuralInputs,
          outputs: stored.success ? stored.data.outputs : undefined,
        }),
      },
    };
  }

  function generate(templateId: string, params: unknown, structuralInputs: unknown) {
    const template = findTemplate(templateId);
    if (!template) return { ok: false, error: 'unknown-template' } as const;
    const result = createSnapshot(template, params, structuralInputs);
    if (!result.ok) return { ok: false, error: 'invalid-project', issues: result.issues } as const;
    return { ok: true, snapshot: result.output } as const;
  }

  const snapshotColumns = (s: ProjectSnapshot) => ({
    templateVersion: s.templateVersion,
    params: s.params,
    structuralInputs: s.structuralInputs,
    snapshot: s,
  });

  async function load(id: string): Promise<Row | undefined> {
    const [row] = await db.select().from(projects).where(eq(projects.id, id));
    return row;
  }

  return {
    async list(): Promise<ProjectSummary[]> {
      const rows = await db.select().from(projects).orderBy(desc(projects.updatedAt));
      return rows.map(summary);
    },

    async get(id: string): Promise<Result<Project>> {
      const row = await load(id);
      return row ? view(row) : { ok: false, error: 'not-found' };
    },

    async create(input: NewProject): Promise<Result<Project>> {
      const generated = generate(input.templateId, input.params, input.structuralInputs ?? {});
      if (!generated.ok) return generated;
      const at = now();
      const [row] = await db
        .insert(projects)
        .values({
          name: input.name,
          status: input.status,
          templateId: input.templateId,
          ...snapshotColumns(generated.snapshot),
          createdAt: at,
          updatedAt: at,
        })
        .returning();
      if (!row) throw new Error('Insert returned no row');
      return view(row);
    },

    /** Changing parameters or inputs regenerates with the template's current version. */
    async update(id: string, changes: ProjectChanges): Promise<Result<Project>> {
      const row = await load(id);
      if (!row) return { ok: false, error: 'not-found' };
      let regenerated = {};
      if (changes.params !== undefined || changes.structuralInputs !== undefined) {
        const generated = generate(
          row.templateId,
          changes.params ?? row.params,
          changes.structuralInputs ?? row.structuralInputs,
        );
        if (!generated.ok) return generated;
        regenerated = snapshotColumns(generated.snapshot);
      }
      const [updated] = await db
        .update(projects)
        .set({
          ...(changes.name !== undefined ? { name: changes.name } : {}),
          ...(changes.status !== undefined ? { status: changes.status } : {}),
          ...regenerated,
          updatedAt: now(),
        })
        .where(eq(projects.id, id))
        .returning();
      if (!updated) return { ok: false, error: 'not-found' };
      return view(updated);
    },

    /** Regenerates from the stored parameters and inputs with the current template version. */
    async regenerate(id: string): Promise<Result<Project>> {
      const row = await load(id);
      if (!row) return { ok: false, error: 'not-found' };
      const generated = generate(row.templateId, row.params, row.structuralInputs);
      if (!generated.ok) return generated;
      const [updated] = await db
        .update(projects)
        .set({ ...snapshotColumns(generated.snapshot), updatedAt: now() })
        .where(eq(projects.id, id))
        .returning();
      if (!updated) return { ok: false, error: 'not-found' };
      return view(updated);
    },
  };
}

export type ProjectService = ReturnType<typeof createProjectService>;
